import{_ as t}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as a}from"./chunks/BDM.scaBLLhv.js";import{_ as s,a as r,b as o,c as i,d as n,e as l,f as u}from"./chunks/M-SS-NFcert.CC0MK3SI.js";import{_ as c}from"./chunks/M-SS.C4V7iNpZ.js";import{_ as d,o as p,c as m,a3 as h}from"./chunks/framework.g9mfNVRQ.js";const P=JSON.parse('{"title":"État du système","description":"","frontmatter":{"source_hash":"972ebaa79c","source_commit":"7a18e7c","i18n_outdated":true},"headers":[],"relativePath":"fr/troubleshoot/systemstatus.md","filePath":"fr/troubleshoot/systemstatus.md"}'),g={name:"fr/troubleshoot/systemstatus.md"};function b(v,e,f,_,x,q){return p(),m("div",null,[...e[0]||(e[0]=[h('<div class="admonition xdrip"><p class="admonition-title"><img src="'+t+'" style="zoom:75%;"></p><p> État du système</p></div><p>L&#39;état du système fournit des informations internes sur l&#39;état du collecteur de xDrip (à partir d&#39;un capteur ou en abonné) ainsi que sur le partage, les abonnés et les montres connectées directement.</p><p>Vous pouvez partager une capture d&#39;écran avec le bouton de partage Android en haut à droite.</p><div class="admonition xdripitem"><p class="admonition-title"><img src="'+a+'" style="zoom:75%;">État du système<span class="symbol"><img src="'+s+'" style="zoom:75%;"></span></p></div><h3 id="classic-status-page" tabindex="-1">Page d&#39;état classique <a class="header-anchor" href="#classic-status-page" aria-label="Permalink to &quot;Page d&#39;état classique {#classic-status-page}&quot;">​</a></h3><p>Cette page affiche des informations sur la version actuellement installée.</p><div class="admonition xdripitem"><p class="admonition-title"><div style="background-color:DodgerBlue;color:white;text-align:center;">  Classic Status Page </div></p><p> Version: a2bbca9-2024.11.26</p></div><p>Les informations de version vous permettent de <a href="https://github.com/NightscoutFoundation/xDrip/releases" target="_blank" rel="noreferrer">retrouver rapidement la version ou pré-version correspondante</a>. Avant la date de version, vous verrez la version de build.</p><p>Tout nom de version qui affiche des informations supplémentaires, comme debug, dev, un nom de montre connectée ou carelink, correspond à une <a href="./../install/download.html#forked-versions">version dérivée (fork)</a> de xDrip et peut ne pas contenir toutes les dernières fonctions de l&#39;application officielle (mais sans doute quelques fonctions en plus).</p><p>Sur cette page, vous trouverez le type de source de données (celle que vous avez choisie pour recevoir vos valeurs de glycémie).</p><div class="admonition xdripitem"><p class="admonition-title">Source de données:</p></div><p>La ligne suivante indique la taille de la base de données de xDrip : la quantité de mémoire qu&#39;elle occupe sur votre téléphone.</p><div class="admonition xdripitem"><p class="admonition-title">Taille de la base de données :</p></div><p>Dans le cas d&#39;un capteur physique, après le type de source de données, vous verrez le nom de l&#39;appareil Bluetooth réellement connecté à xDrip. Vous voyez aussi l&#39;état de la connexion ; gardez à l&#39;esprit que certains capteurs ne se connectent que brièvement toutes les 5 minutes, et Not connected n&#39;indique donc pas forcément un vrai problème.</p><div class="admonition xdripitem"><p class="admonition-title">Bluetooth Device:</p></div><div class="admonition xdripitem"><p class="admonition-title">Connection Status:</p></div><div class="admonition xdripitem"><p class="admonition-title">Sensor Start:</p></div><p>Cette page ne se met pas à jour automatiquement : appuyez sur les flèches arrondies pour la rafraîchir.</p><img src="'+r+'" style="zoom:75%;"><h4 id="restart-collector-forget-device" tabindex="-1">Redémarrer le collecteur - Oublier ce périphérique <a class="header-anchor" href="#restart-collector-forget-device" aria-label="Permalink to &quot;Redémarrer le collecteur - Oublier ce périphérique {#restart-collector-forget-device}&quot;">​</a></h4><div class="admonition xdrip"><p class="admonition-title"><span style="background-color:white;color:black;"> REDÉMARRER LE COLLECTEUR </span> <span style="background-color:white;color:black;"> OUBLIER CE PÉRIPHÉRIQUE </span></p></div><p>Redémarrer le collecteur relance le mécanisme de collecte interne de xDrip. L&#39;effet dépend de la source de données.</p><p>Oublier ce périphérique n&#39;a d&#39;effet que lorsque xDrip est connecté à un appareil en Bluetooth.<br> L&#39;appareil sera déconnecté et vous devrez lancer un scan Bluetooth depuis le menu principal pour rétablir la connexion.</p><h3 id="advanced-status-page" tabindex="-1">Page d&#39;état avancée <a class="header-anchor" href="#advanced-status-page" aria-label="Permalink to &quot;Page d&#39;état avancée {#advanced-status-page}&quot;">​</a></h3><p>La plupart des sources de données disposent d&#39;un onglet d&#39;état avancé. Faites glisser votre doigt vers la gauche sur l&#39;écran pour l&#39;afficher.</p><img src="'+c+'" style="zoom:75%;"><h5 id="buggy-samsung" tabindex="-1">Buggy Samsung <a class="header-anchor" href="#buggy-samsung" aria-label="Permalink to &quot;Buggy Samsung {#buggy-samsung}&quot;">​</a></h5><p>Renommé Buggy Handset, car d&#39;autres appareils présentent cette non-conformité.</p><h5 id="buggy-handset" tabindex="-1">Buggy Handset <a class="header-anchor" href="#buggy-handset" aria-label="Permalink to &quot;Buggy Handset {#buggy-handset}&quot;">​</a></h5><p>Il ne s&#39;agit pas d&#39;une erreur : cela signifie simplement que xDrip <a href="https://github.com/NightscoutFoundation/xDrip/issues/435" target="_blank" rel="noreferrer">corrige</a> une non-conformité d&#39;Android sur certains appareils.<br> Il est recommandé de <a href="./../use/misc.html#wake-workarounds">l&#39;activer</a> en cas de pertes de données.</p><img src="'+o+'" style="zoom:75%;"><h5 id="slowest-wake-up" tabindex="-1">Slowest wake-up <a class="header-anchor" href="#slowest-wake-up" aria-label="Permalink to &quot;Slowest wake-up {#slowest-wake-up}&quot;">​</a></h5><p>Indique quand xDrip a reçu les données par rapport à l&#39;heure attendue. Quelques secondes sont acceptables, mais des minutes peuvent signaler un problème de connectivité.</p><img src="'+i+'" style="zoom:75%;"><h4 id="g6-g7-1-and-1" tabindex="-1">G6, G7, 1 et 1+ <a class="header-anchor" href="#g6-g7-1-and-1" aria-label="Permalink to &quot;G6, G7, 1 et 1+ {#g6-g7-1-and-1}&quot;">​</a></h4><p>Voir les pages dédiées <a href="./g6.html">G6/ONE</a> et <a href="./g7.html">G7/ONE+</a>. Plus de détails sur la connectivité <a href="https://navid200.github.io/xDrip/docs/Connectivity-troubleshoot.html" target="_blank" rel="noreferrer">ici</a>.</p><h4 id="libre-bluetooth" tabindex="-1">Libre Bluetooth <a class="header-anchor" href="#libre-bluetooth" aria-label="Permalink to &quot;Libre Bluetooth {#libre-bluetooth}&quot;">​</a></h4><p>Si vous utilisez un transmetteur, consultez la page dédiée <a href="./librebridge.html">ici</a>.</p><p>Si vous utilisez un Libre 2 en direct (c&#39;est-à-dire sans transmetteur), consultez la page dédiée <a href="./libre2direct.html">ici</a>.</p><h4 id="xdrip-sync-follower" tabindex="-1">Abonné xDrip Sync <a class="header-anchor" href="#xdrip-sync-follower" aria-label="Permalink to &quot;Abonné xDrip Sync {#xdrip-sync-follower}&quot;">​</a></h4><div class="warning custom-block"><p class="custom-block-title">Travail en cours</p><p>En juillet 2024, Google a arrêté l&#39;<a href="https://firebase.google.com/docs/cloud-messaging/migrate-v1" target="_blank" rel="noreferrer">API Firebase</a> obsolète que xDrip utilisait pour xDrip Sync.<br> Mettez à jour xDrip vers une version du <a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2024.07.23" target="_blank" rel="noreferrer">23 juillet 2024</a> ou plus récente.</p></div><p>L&#39;abonné xDrip est très simple à <a href="./../use/syncsetup.html">configurer</a>. En cas de problème, il s&#39;agit la plupart du temps d&#39;un souci de connexion réseau ou des services Google Play.<br> Il est recommandé d&#39;avoir aussi <a href="https://nightscout.github.io/" target="_blank" rel="noreferrer">Nightscout</a> comme solution d&#39;abonné de secours lors du dépannage ou pour suivre un enfant.</p><img src="'+n+'" style="zoom:75%;"><p>Les abonnés s&#39;ajoutent à la liste lorsqu&#39;ils sont identifiés ; si vous supprimez un abonné, il peut s&#39;écouler un certain temps avant qu&#39;il disparaisse réellement de la liste.</p><p>Pour les problèmes de configuration initiale, consultez <a href="./../install/xdripfollower.html">cette page</a>.</p><h4 id="nightscout-follower" tabindex="-1">Abonné Nightscout <a class="header-anchor" href="#nightscout-follower" aria-label="Permalink to &quot;Abonné Nightscout {#nightscout-follower}&quot;">​</a></h4><p>La page d&#39;état avancée montre l&#39;activité lors du téléchargement depuis Nightscout. Si aucune donnée n&#39;est disponible, vérifiez que Nightscout contient des valeurs de glycémie récentes.</p><p>En cas d&#39;échec du téléchargement, si votre site Nightscout est régulièrement mis à jour par l&#39;appareil principal et que vous voyez des erreurs de téléchargement NS, cela peut venir de problèmes réseau. Désactivez le Wi-Fi ou les données mobiles, puis faites l&#39;inverse, pour écarter ce problème.</p><p>Si cela n&#39;a jamais fonctionné, vérifiez que vous avez correctement <a href="./../install/nightscoutfollower.html">configuré</a> l&#39;URL de votre abonné.</p><img src="'+l+'" style="zoom:75%;"><p>Les anciennes versions d&#39;Android peuvent utiliser des certificats expirés et empêcher ainsi le fonctionnement de l&#39;abonné Nightscout. Il n&#39;existe pas de solution de contournement.</p><img src="'+u+'" style="zoom:75%;"><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Dernière modification le 23/11/2026</em></a></p>',54)])])}const S=d(g,[["render",b]]);export{P as __pageData,S as default};
